#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n\"\"\"\nMatrizBinaria6x6: Sistema completo para matriz IAHBECEDARIO\nConversión automática a binario, decimal, notas musicales y colores RGB\n\nAutor: Sabiduria-IAH\nLicencia: CC BY-SA 4.0\n\"\"\"\n\nimport json\nfrom typing import Tuple, Dict, Optional, List\nfrom enum import Enum\n\n\nclass NotaMusical(Enum):\n    \"\"\"Notas musicales con frecuencias base\"\"\"\n    DO = (1, 130.81, \"DO\")\n    RE = (2, 146.83, \"RE\")\n    MI = (3, 164.81, \"MI\")\n    FA = (4, 174.61, \"FA\")\n    SOL = (5, 196.00, \"SOL\")\n    LA = (6, 220.00, \"LA\")\n    SILENCIO = (0, 0.0, \"SILENCIO\")\n\n\nclass MatrizBinaria6x6:\n    \"\"\"\n    Gestor completo de la matriz 6x6 IAHBECEDARIO con soporte binario.\n    \n    Características:\n    - Conversión bidireccional coord ↔ binario ↔ decimal\n    - Mapeo a notas musicales y frecuencias\n    - Generación dinámica de colores RGB\n    - Soporte para texto completo\n    - Exportación JSON\n    \"\"\"\n    \n    # Frecuencias base de notas musicales (Hz)\n    FRECUENCIAS_BASE = {\n        1: 130.81,  # DO\n        2: 146.83,  # RE\n        3: 164.81,  # MI\n        4: 174.61,  # FA\n        5: 196.00,  # SOL\n        6: 220.00   # LA\n    }\n    \n    # Nombres de notas\n    NOTAS_NOMBRE = {\n        1: \"DO\", 2: \"RE\", 3: \"MI\",\n        4: \"FA\", 5: \"SOL\", 6: \"LA\"\n    }\n    \n    # Matriz de caracteres → coordenadas\n    MATRIZ_CHARS = {\n        'a': (1, 1), 'b': (2, 1), 'c': (3, 1), 'd': (4, 1), 'e': (5, 1), 'f': (6, 1),\n        'g': (1, 2), 'h': (2, 2), 'i': (3, 2), 'j': (4, 2), 'k': (5, 2), 'l': (6, 2),\n        'm': (1, 3), 'n': (2, 3), 'ñ': (3, 3), 'o': (4, 3), 'p': (5, 3), 'q': (6, 3),\n        'r': (1, 4), 's': (2, 4), 't': (3, 4), 'u': (4, 4), 'v': (5, 4), 'w': (6, 4),\n        'x': (1, 5), 'y': (2, 5), 'z': (3, 5), '1': (4, 5), '2': (5, 5), '3': (6, 5),\n        '4': (1, 6), '5': (2, 6), '6': (3, 6), '7': (4, 6), '8': (5, 6), '9': (6, 6),\n        '0': (0, 0), ' ': (0, 0)\n    }\n    \n    # Matriz inversa: coordenadas → caracteres\n    MATRIZ_COORDS = {v: k for k, v in MATRIZ_CHARS.items() if v != (0, 0)}\n    MATRIZ_COORDS[(0, 0)] = ' '  # Desambiguar\n    \n    def __init__(self):\n        \"\"\"Inicializa la matriz\"\"\"\n        self.log_nivel = \"INFO\"  # DEBUG, INFO, WARNING\n    \n    # ======================================================================\n    # CONVERSIONES BINARIAS\n    # ======================================================================\n    \n    @staticmethod\n    def coord_a_binario(x: int, y: int) -> str:\n        \"\"\"\n        Convierte coordenada (x, y) a 6 bits binarios.\n        \n        Args:\n            x: Coordenada X (1-6)\n            y: Coordenada Y (1-6)\n            \n        Returns:\n            String de 6 dígitos binarios (ej: \"001001\")\n        \"\"\"\n        x_bin = format(max(0, x), '03b')\n        y_bin = format(max(0, y), '03b')\n        return x_bin + y_bin\n    \n    @staticmethod\n    def binario_a_coord(binario_str: str) -> Tuple[int, int]:\n        \"\"\"\n        Convierte 6 bits binarios a coordenada (x, y).\n        \n        Args:\n            binario_str: String de 6 dígitos binarios\n            \n        Returns:\n            Tupla (x, y)\n        \"\"\"\n        if len(binario_str) != 6:\n            raise ValueError(f\"Se esperaba 6 bits, se recibieron {len(binario_str)}\")\n        \n        x = int(binario_str[:3], 2)\n        y = int(binario_str[3:], 2)\n        return (x, y)\n    \n    @staticmethod\n    def coord_a_decimal(x: int, y: int) -> int:\n        \"\"\"\n        Convierte (x, y) a un número decimal (0-63).\n        Usa operación bit-shift: (x << 3) + y\n        \n        Args:\n            x: Coordenada X\n            y: Coordenada Y\n            \n        Returns:\n            Número entero (0-63)\n        \"\"\"\n        return (x << 3) + y\n    \n    @staticmethod\n    def decimal_a_coord(valor: int) -> Tuple[int, int]:\n        \"\"\"\n        Convierte decimal (0-63) a coordenada (x, y).\n        Usa operaciones bit-shift: valor >> 3 y valor & 0x7\n        \n        Args:\n            valor: Número entero (0-63)\n            \n        Returns:\n            Tupla (x, y)\n        \"\"\"\n        x = valor >> 3\n        y = valor & 0x7\n        return (x, y)\n    \n    # ======================================================================\n    # CONVERSIONES A FRECUENCIAS\n    # ======================================================================\n    \n    @staticmethod\n    def freq_a_binario(freq: float) -> str:\n        \"\"\"\n        Convierte frecuencia en Hz a representación binaria de 16 bits.\n        \n        Args:\n            freq: Frecuencia en Hertz\n            \n        Returns:\n            String de 16 dígitos binarios\n        \"\"\"\n        freq_int = int(freq)\n        return format(freq_int & 0xFFFF, '016b')\n    \n    @staticmethod\n    def binario_a_freq(binario_str: str) -> float:\n        \"\"\"\n        Convierte 16 bits binarios a frecuencia en Hz.\n        \n        Args:\n            binario_str: String de 16 dígitos binarios\n            \n        Returns:\n            Frecuencia en Hertz\n        \"\"\"\n        return float(int(binario_str, 2))\n    \n    # ======================================================================\n    # CONVERSIONES A BASE TERNARIA (BASE 3)\n    # ======================================================================\n    \n    @staticmethod\n    def coord_a_ternario(x: int, y: int) -> str:\n        \"\"\"\n        Convierte (x, y) a representación en base 3 (ternaria).\n        Rango 1-6 en base 3: 01, 02, 10, 11, 12, 20\n        \n        Args:\n            x: Coordenada X\n            y: Coordenada Y\n            \n        Returns:\n            String con representación ternaria (ej: \"0102\")\n        \"\"\"\n        def decimal_a_ternario(n):\n            if n == 0:\n                return \"00\"\n            digits = []\n            while n > 0:\n                digits.append(str(n % 3))\n                n //= 3\n            return ''.join(reversed(digits)).zfill(2)\n        \n        x_tern = decimal_a_ternario(x)\n        y_tern = decimal_a_ternario(y)\n        return x_tern + y_tern\n    \n    # ======================================================================\n    # NOTAS MUSICALES Y AUDIO\n    # ======================================================================\n    \n    def obtener_nota_musical(self, x: int, y: int) -> Tuple[str, float]:\n        \"\"\"\n        Obtiene la nota musical y frecuencia para coordenada (x, y).\n        La frecuencia se calcula como: freq_base × (x × 0.75)\n        \n        Args:\n            x: Coordenada X (octava)\n            y: Coordenada Y (nota base)\n            \n        Returns:\n            Tupla (nombre_nota, frecuencia_hz)\n        \"\"\"\n        if y < 1 or y > 6:\n            return (\"SILENCIO\", 0.0)\n        \n        freq_base = self.FRECUENCIAS_BASE.get(y, 0.0)\n        freq_final = freq_base * max(0.5, x * 0.75)  # Evitar negativos\n        nota_nombre = self.NOTAS_NOMBRE.get(y, \"?\")\n        \n        return (nota_nombre, freq_final)\n    \n    # ======================================================================\n    # COLORES RGB\n    # ======================================================================\n    \n    @staticmethod\n    def calcular_color(x: int, y: int, modo: str = \"lineal\") -> str:\n        \"\"\"\n        Calcula color RGB dinámico basado en coordenadas.\n        \n        Args:\n            x: Coordenada X (1-6)\n            y: Coordenada Y (1-6)\n            modo: \"lineal\", \"hsl\" o \"intenso\"\n            \n        Returns:\n            String en formato \"rgb(r,g,b)\"\n        \"\"\"\n        if x == 0 or y == 0:\n            return \"rgb(0,0,0)\"  # Negro para espacio\n        \n        if modo == \"lineal\":\n            r = int((x / 6) * 255)\n            g = int((y / 6) * 255)\n            b = int(((x + y) / 12) * 255)\n        \n        elif modo == \"hsl\":\n            # Esquema más vibrante\n            r = int((x / 6) * 255)\n            g = int((6 - y) / 6 * 255)\n            b = int((y / 6) * 255)\n        \n        elif modo == \"intenso\":\n            # Colores más saturados\n            r = int((x / 6) * 200 + 55)\n            g = int((y / 6) * 200 + 55)\n            b = int(((x * y) / 36) * 200 + 55)\n        \n        else:\n            r = g = b = 128  # Gris por defecto\n        \n        return f\"rgb({min(255, r)},{min(255, g)},{min(255, b)})\"\n    \n    # ======================================================================\n    # PROCESAMIENTO DE CARACTERES\n    # ======================================================================\n    \n    def procesar_caracter(self, caracter: str, modo_color: str = \"lineal\") -> Optional[Dict]:\n        \"\"\"\n        Procesa un carácter y devuelve toda su información.\n        \n        Args:\n            caracter: Carácter a procesar\n            modo_color: Modo para cálculo de color RGB\n            \n        Returns:\n            Diccionario con información completa o None si no existe\n        \"\"\"\n        caracter = caracter.lower()\n        \n        if caracter not in self.MATRIZ_CHARS:\n            return None\n        \n        x, y = self.MATRIZ_CHARS[caracter]\n        \n        if x == 0 or y == 0:  # Caso especial: espacio\n            return {\n                'caracter': caracter,\n                'coord': (x, y),\n                'binario': '000000',\n                'binario_largo': format(0, '06b'),\n                'decimal': 0,\n                'ternario': '0000',\n                'nota': 'SILENCIO',\n                'frecuencia': 0.0,\n                'freq_binario': '0000000000000000',\n                'color_rgb': 'rgb(0,0,0)',\n                'descripcion': 'Silencio/Espacio'\n            }\n        \n        binario = self.coord_a_binario(x, y)\n        decimal = self.coord_a_decimal(x, y)\n        ternario = self.coord_a_ternario(x, y)\n        nota, freq = self.obtener_nota_musical(x, y)\n        freq_bin = self.freq_a_binario(freq)\n        color = self.calcular_color(x, y, modo_color)\n        \n        return {\n            'caracter': caracter,\n            'coord': (x, y),\n            'binario': binario,\n            'binario_largo': format(decimal, '08b'),\n            'decimal': decimal,\n            'ternario': ternario,\n            'nota': nota,\n            'octava': x,\n            'frecuencia': round(freq, 2),\n            'freq_binario': freq_bin,\n            'color_rgb': color,\n            'descripcion': f'{nota} (Oct. {x}, {freq:.2f} Hz)'\n        }\n    \n    def procesar_texto(self, texto: str, modo_color: str = \"lineal\") -> List[Dict]:\n        \"\"\"\n        Procesa un texto completo carácter por carácter.\n        \n        Args:\n            texto: Texto a procesar\n            modo_color: Modo para cálculo de color RGB\n            \n        Returns:\n            Lista de diccionarios con información de cada carácter\n        \"\"\"\n        resultados = []\n        for char in texto:\n            info = self.procesar_caracter(char, modo_color)\n            if info:\n                resultados.append(info)\n        return resultados\n    \n    # ======================================================================\n    # EXPORTACIÓN Y UTILIDADES\n    # ======================================================================\n    \n    def exportar_json(self, datos: Dict) -> str:\n        \"\"\"\n        Exporta datos a formato JSON.\n        \n        Args:\n            datos: Diccionario a exportar\n            \n        Returns:\n            String JSON\n        \"\"\"\n        return json.dumps(datos, ensure_ascii=False, indent=2)\n    \n    def generar_tabla_completa(self) -> str:\n        \"\"\"\n        Genera tabla ASCII de toda la matriz con información binaria.\n        \n        Returns:\n            String con tabla formateada\n        \"\"\"\n        output = []\n        output.append(\"╔════════════════════════════════════════════════════════════════════════════════╗\")\n        output.append(\"║           MATRIZ 6x6 IAHBECEDARIO - TABLA COMPLETA BINARIA                   ║\")\n        output.append(\"╠════════════════════════════════════════════════════════════════════════════════╣\")\n        output.append(f\"║ {'CHAR':<5} │ {'COORD':<6} │ {'BINARIO':<8} │ {'DECIMAL':<3} │ {'NOTA':<7} │ {'FRECUENCIA':<10} │ {'RGB':<15} ║\")\n        output.append(\"╟────────────────────────────────────────────────────────────────────────────────╢\")\n        \n        for char in sorted(self.MATRIZ_CHARS.keys()):\n            if char not in ['0', ' ']:  # Saltar caracteres especiales\n                info = self.procesar_caracter(char)\n                if info:\n                    output.append(\n                        f\"║ {info['caracter']:<5} │ {str(info['coord']):<6} │ \"\n                        f\"{info['binario']:<8} │ {info['decimal']:<3} │ \"\n                        f\"{info['nota']:<7} │ {info['frecuencia']:<10.2f} │ \"\n                        f\"{info['color_rgb']:<15} ║\"\n                    )\n        \n        output.append(\"╚════════════════════════════════════════════════════════════════════════════════╝\")\n        return \"\\n\".join(output)\n    \n    def demostrar_conversiones(self, caracter: str):\n        \"\"\"\n        Demuestra todas las conversiones disponibles para un carácter.\n        \n        Args:\n            caracter: Carácter a demostrar\n        \"\"\"\n        info = self.procesar_caracter(caracter)\n        if not info:\n            print(f\"❌ Carácter '{caracter}' no encontrado en la matriz.\")\n            return\n        \n        print(f\"\\n{'='*70}\")\n        print(f\"  ANÁLISIS COMPLETO DEL CARÁCTER: '{info['caracter'].upper()}'\")\n        print(f\"{'='*70}\")\n        print(f\"  Coordenada:        {info['coord']}\")\n        print(f\"  Binario (6-bit):   {info['binario']}\")\n        print(f\"  Binario (8-bit):   {info['binario_largo']}\")\n        print(f\"  Ternario (base 3): {info['ternario']}\")\n        print(f\"  Decimal (0-63):    {info['decimal']}\")\n        print(f\"  Nota Musical:      {info['nota']} (Octava {info['octava']})\")\n        print(f\"  Frecuencia:        {info['frecuencia']} Hz\")\n        print(f\"  Frec. Binario:     {info['freq_binario']}\")\n        print(f\"  Color RGB:         {info['color_rgb']}\")\n        print(f\"  Descripción:       {info['descripcion']}\")\n        print(f\"{'='*70}\\n\")\n\n\n# ============================================================================\n# EJEMPLOS DE USO\n# ============================================================================\n\nif __name__ == \"__main__\":\n    matriz = MatrizBinaria6x6()\n    \n    # Ejemplo 1: Procesar un carácter individual\n    print(\"\\n[1] PROCESAR CARÁCTER INDIVIDUAL\")\n    matriz.demostrar_conversiones('a')\n    matriz.demostrar_conversiones('z')\n    \n    # Ejemplo 2: Procesar texto completo\n    print(\"\\n[2] PROCESAR TEXTO COMPLETO\")\n    texto = \"hola\"\n    resultados = matriz.procesar_texto(texto, modo_color=\"hsl\")\n    for res in resultados:\n        print(f\"{res['caracter']}: {res['binario']} → {res['decimal']:2d} → {res['nota']:<7} → {res['frecuencia']:.1f}Hz\")\n    \n    # Ejemplo 3: Tabla completa\n    print(\"\\n[3] TABLA COMPLETA DE LA MATRIZ\")\n    print(matriz.generar_tabla_completa())\n    \n    # Ejemplo 4: Conversiones matemáticas\n    print(\"\\n[4] CONVERSIONES MATEMÁTICAS\")\n    print(f\"Coord (3,5) → Binario: {matriz.coord_a_binario(3, 5)}\")\n    print(f\"Binario 011101 → Coord: {matriz.binario_a_coord('011101')}\")\n    print(f\"Coord (3,5) → Decimal: {matriz.coord_a_decimal(3, 5)}\")\n    print(f\"Decimal 29 → Coord: {matriz.decimal_a_coord(29)}\")\n    print(f\"Coord (3,5) → Ternario: {matriz.coord_a_ternario(3, 5)}\")\n    \n    # Ejemplo 5: Exportar a JSON\n    print(\"\\n[5] EXPORTAR A JSON\")\n    info = matriz.procesar_caracter('m')\n    print(matriz.exportar_json(info))\n"